"""ADR 008 — the calibration controls generated by run_judge_eval.py must
actually change the wording (positive) or the content (negative) of the
golden text, and must route through the real GEval metric rather than a
hand-rolled prompt (the bug found in the first draft of this branch: the
judge was never actually called, and calibration always "passed" via a
hardcoded 0.7/0.3 fallback score)."""

import pytest

from backend.tests.evaluation.run_judge_eval import (
    _faithful_reword,
    _judge_score,
    _material_change,
)


def test_faithful_reword_changes_wording():
    original = "The party shall terminate the agreement within 30 days."
    reworded = _faithful_reword(original)
    assert reworded != original


def test_faithful_reword_preserves_the_number():
    original = "Either party must provide 30 days written notice."
    reworded = _faithful_reword(original)
    assert "30" in reworded


def test_material_change_alters_a_duration_if_present():
    original = "Either party may terminate with 30 days written notice."
    changed = _material_change(original)
    assert changed != original
    assert "days written notice" in changed  # only the number should change


def test_material_change_falls_back_to_truncation_without_a_duration():
    original = "This clause has no duration mentioned in it at all here."
    changed = _material_change(original)
    assert changed != original
    assert len(changed) < len(original)


@pytest.mark.asyncio
async def test_judge_score_calls_the_metrics_a_measure(monkeypatch):
    calls = []

    class FakeMetric:
        async def a_measure(self, test_case):
            calls.append((test_case.actual_output, test_case.expected_output))
            return 0.9

    score = await _judge_score(FakeMetric(), "actual text", "expected text")
    assert score == 0.9
    assert calls == [("actual text", "expected text")]
